var countGoodNumbers = function(n) {
  const MOD = 1000000007n;
  const bigN = BigInt(n);
  const evenCount = (bigN + 1n) / 2n;
  const oddCount = bigN / 2n;

  function modPow(base, exp) {
    let res = 1n;
    base %= MOD;
    while (exp > 0n) {
      if (exp % 2n === 1n) res = (res * base) % MOD;
      base = (base * base) % MOD;
      exp /= 2n;
    }
    return res;
  }

  const p5 = modPow(5n, evenCount);
  const p4 = modPow(4n, oddCount);
  return Number((p5 * p4) % MOD);
};
